#!/bin/bash
# Send a chat message and print state changes until the run ends. Usage: track.sh "<text>" <cardId> [maxSec]
cd "$(dirname "$0")" || exit 1; N=${NODE:-node}; OUT="${EGDESK_QA_OUT:-/tmp/egdesk-real-window-qa}"; mkdir -p "$OUT"; T0=$(date +%s); MAX=${3:-150}; echo "send $(date +%H:%M:%S)"; $N send-chat.mjs "$1"; PREV=""
while [ $(( $(date +%s) - T0 )) -lt $MAX ]; do sleep 2; R=$($N mn.mjs exec "const chat=document.querySelector('.egd-chat-card'); const t=(chat.innerText||'').replace(/\\s+/g,' '); const working=[...chat.querySelectorAll('button')].some(b=>/^중지\$/.test((b.textContent||b.getAttribute('aria-label')||'').trim())); const c=document.getElementById('$2'); const url=(c?.querySelector('.egd-card-url')?.value||c?.querySelector('input')?.value||''); return JSON.stringify({working, url:String(url).slice(0,64), tail:t.slice(-120)});" 600); if [ "$R" != "$PREV" ]; then echo "+$(( $(date +%s) - T0 ))s $R" | cut -c1-300; PREV="$R"; fi; case "$R" in *'"working":false'*) [ $(( $(date +%s) - T0 )) -gt 5 ] && break;; esac; done; echo "end +$(( $(date +%s) - T0 ))s"
